CREATE OR REPLACE FUNCTION public.finance_invoice_balances() RETURNS TABLE(order_id uuid,invoice_number text,client_name text,invoice_state text,total numeric,paid numeric,balance numeric,status text,due_date date) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; t jsonb; BEGIN IF NOT public.can_access('finance') THEN RAISE EXCEPTION 'Finance tidak berizin'; END IF; FOR o IN SELECT r.* FROM public.orders r WHERE r.tenant_id=public.active_tenant_id() AND r.deleted_at IS NULL AND r.invoice_state IN ('issued','cancelled') LOOP t:=public.sales_totals('orders',o.id); order_id:=o.id;invoice_number:=o.invoice_number;client_name:=o.client_name;invoice_state:=o.invoice_state;total:=(t->>'total')::numeric;paid:=(t->>'paid')::numeric;balance:=CASE WHEN o.invoice_state='cancelled' THEN 0 ELSE (t->>'balance')::numeric END;status:=t->>'state';due_date:=o.due_date;RETURN NEXT; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.track_sales_sequence() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE num text; typ text; n bigint; code text; BEGIN IF TG_TABLE_NAME='quotations' THEN num:=NEW.quotation_number;typ:='quotation'; ELSE num:=NEW.invoice_number;typ:='invoice'; END IF; code:=regexp_replace(upper(NEW.client_name),'[^A-Z0-9]','','g'); IF num ~ '^(INV|PO|QUO)/[^/]+/[0-9]{4}/[0-9]{2}/[0-9]+$' THEN n:=(regexp_match(num,'/([0-9]+)$'))[1]::bigint; INSERT INTO public.document_sequences(tenant_id,client_code,document_type,sequence) VALUES(NEW.tenant_id,code,typ,n) ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=GREATEST(public.document_sequences.sequence,EXCLUDED.sequence); END IF; IF TG_TABLE_NAME='orders' THEN IF NEW.order_number ~ '^PO/[^/]+/[0-9]{4}/[0-9]{2}/[0-9]+$' THEN n:=(regexp_match(NEW.order_number,'/([0-9]+)$'))[1]::bigint; INSERT INTO public.document_sequences(tenant_id,client_code,document_type,sequence) VALUES(NEW.tenant_id,code,'order',n) ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=GREATEST(public.document_sequences.sequence,EXCLUDED.sequence); END IF; END IF; RETURN NEW; END $$;